CREATE TABLE public.lesson_bunny_videos (lesson_id uuid PRIMARY KEY REFERENCES public.lessons(id) ON DELETE CASCADE, encrypted_video text NOT NULL, video_fingerprint text NOT NULL UNIQUE, library_id text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lesson_bunny_videos TO authenticated; GRANT ALL ON public.lesson_bunny_videos TO service_role;
ALTER TABLE public.lesson_bunny_videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY bunny_mapping_admin ON public.lesson_bunny_videos FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.bunny_security_checks (id boolean PRIMARY KEY DEFAULT true CHECK(id), embed_tokens boolean NOT NULL DEFAULT false, preview_referrer boolean NOT NULL DEFAULT false, unsigned_denied boolean NOT NULL DEFAULT false, direct_media_denied boolean NOT NULL DEFAULT false, verified_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.bunny_security_checks TO authenticated; GRANT ALL ON public.bunny_security_checks TO service_role;
ALTER TABLE public.bunny_security_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY bunny_security_admin ON public.bunny_security_checks FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.bunny_mapping_draft_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM public.lessons l JOIN public.modules m ON m.id=l.module_id JOIN public.courses c ON c.id=m.course_id WHERE l.id=COALESCE(NEW.lesson_id,OLD.lesson_id) AND l.status='draft') THEN RAISE EXCEPTION 'Admin and draft lesson required'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER bunny_mapping_draft_guard BEFORE INSERT OR UPDATE OR DELETE ON public.lesson_bunny_videos FOR EACH ROW EXECUTE FUNCTION public.bunny_mapping_draft_only();
CREATE FUNCTION public.lms_bunny_playback_mapping(p_lesson uuid,p_hash text) RETURNS TABLE(encrypted_video text,library_id text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid text:=auth.jwt()->>'session_id'; BEGIN
IF auth.uid() IS NULL OR sid IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id::text=sid AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Sign in again'; END IF;
IF EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND session_id=sid AND revoked_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND session_id=sid AND token_hash=p_hash AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Registered active browser required'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.bunny_security_checks WHERE id=true AND embed_tokens AND preview_referrer AND unsigned_denied AND direct_media_denied AND verified_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'Bunny security configuration unverified'; END IF;
RETURN QUERY SELECT v.encrypted_video,v.library_id FROM public.lesson_bunny_videos v JOIN public.lessons l ON l.id=v.lesson_id JOIN public.modules m ON m.id=l.module_id JOIN public.courses c ON c.id=m.course_id JOIN public.enrollments e ON e.course_id=c.id WHERE l.id=p_lesson AND l.status='published' AND c.status='published' AND e.user_id=auth.uid() AND e.starts_at<=now() AND e.expires_at>now() AND e.revoked_at IS NULL;
END $$;
REVOKE ALL ON FUNCTION public.lms_bunny_playback_mapping(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_bunny_playback_mapping(uuid,text) TO authenticated;